if (!/<h1\s*>/i.test(code)) {
  throw new Error("No <h1> found — the most important heading on a page uses the level-1 heading tag.");
}

if (/<p\s*>/i.test(code)) {
  throw new Error("Still a <p> element present — replace it, don't add alongside it.");
}

const m = code.match(/<h1\s*>([\s\S]*?)<\/h1\s*>/i);
if (!m || m[1].trim() !== "My First Page") {
  throw new Error("The heading text must be exactly: My First Page");
}
